def scene_of(text: str, cap: int = 190) -> str:
    """The opening of an authored scene as one clean clause: drop a leading ALL-CAPS label, stop at the first sentence
    end, or at the last comma before `cap` characters, and end with a period."""
    t = re.sub(r"\s+", " ", text.strip())
    t = re.sub(r"^[A-Z][A-Z ]{5,}\.\s+", "", t)
    m = re.match(r"(.{40,%d}?[.;])\s" % cap, t + " ")
    if m:
        s = m.group(1)
    else:
        cut = t[:cap]
        s = cut[:cut.rfind(",")] if "," in cut[40:] else cut.rsplit(" ", 1)[0]
    return s.rstrip(".;, ") + "."


def direction(scene_text: str, index: int, need: int) -> str:
    """Genuine direction of at least `need` characters, from clauses rotated by `index`. Fails loudly if exhausted."""
    scene = scene_of(scene_text)
    out, n = [], len(CLAUSES)
    total = 0
    for k in range(n):
        c = CLAUSES[(index * 7 + k) % n].format(scene=scene)
        out.append(c)
        total += len(c) + 1
        if total >= need:
            return " ".join(out)
    raise RuntimeError("direction bank exhausted: need %d chars, have %d; add real clauses, never pad" % (need, total))
